INSERT INTO audit_log (user_id, action, target, created_at)
SELECT u.id, 'login', NULL, datetime((SELECT d FROM demo_days WHERE rn = 1) || ' 19:00:00', '-3 hours', '-' || (1 + u.id % 6) || ' days')
FROM users u WHERE u.role = 'parent' AND (u.id % 100) < 55 AND NOT EXISTS (SELECT 1 FROM audit_log al WHERE al.user_id = u.id AND al.action = 'login');

DROP TABLE IF EXISTS demo_days;
